static void _handle_activate_bounce ( Node_t * nodep , Port_t * portp ) { if ( sm_config . portBounceLogLimit == PORT_BOUNCE_LOG_NO_LIMIT || topology_port_bounce_log_num < sm_config . portBounceLogLimit ) { IB_LOG_WARN_FMT ( __func__ , "Arm/activate port for node %s guid " FMT_U64 " port %d: port has bounced since programming start, requesting resweep" , sm_nodeDescString ( nodep ) , nodep -> nodeInfo . NodeGUID , portp -> index ) ; topology_port_bounce_log_num ++ ; } sm_request_resweep ( 0 , 0 , SM_SWEEP_REASON_UNEXPECTED_BOUNCE ) ; } 